/** Whether a module has a drawing of its own. */
export function hasIllustration(key: string) {
  return key in DRAWINGS;
}

/**
 * The four variables every drawing is painted with. A caller sets them to the
 * module's tone, and the same markup comes out blue, green or amber.
 */
export function Illustration({
  featureKey, vars, className,
}: {
  featureKey: string;
  vars: React.CSSProperties;
  className?: string;
}) {
  const d = DRAWINGS[featureKey];
  if (!d) return null;
  return (
    <svg
      viewBox={d.viewBox}
      className={cn("h-full w-full", className)}
      style={vars}
      preserveAspectRatio="xMidYMid meet"
      aria-hidden="true"
      focusable="false"
      dangerouslySetInnerHTML={{ __html: d.body }}
    />
  );
}
